[STAThread]static int Main(){try{var folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-temporais");var p=Project.CreateSample();p.Source.Model=SourceModel.GeradorSincrono;p.Source.ShortCircuitKA=0;p.Source.LineVoltage=380;p.Source.GeneratorRatedKva=0;p.Source.GeneratorXdPercent=0;p.Frequency=50;var c=p.Boards[0].Circuits[0];string docHash=System.Text.RegularExpressions.Regex.Match(File.ReadAllText(Path.Combine(folder,"stamford-digitization.json")),"\"sha256_pdf\"\\s*:\\s*\"([a-f0-9]{64})\"").Groups[1].Value;Check(docHash.Length==64,"original PDF hash loaded");var metadata=new FaultTimeBinding{Kind=FaultTraceKind.SymmetricRmsEnvelope,Interpolation=TraceInterpolation.LogLog,FrequencyHz=50,FaultCase="Falta3F nos terminais, simétrica AC, sem pré-carga",EquipmentReference="STAMFORD S7L1D-K4 W312 estrela separadamente excitado380V50Hz",Reference="ES10459201 RevB09.09.2025 p6, curva vermelha50Hz; https://www.stamford-avk.com/sites/stamfordavk/files/ES10459201_S7L1D-K4-B-W312.pdf",DataVersion="RevB09.09.2025",Conditions="Estrela, excitação separada, velocidade nominal, sem carga, fator380V1.00; somente exemplo documental, parâmetros completos da máquina não cadastrados",Acquisition="12 pontos aproximados digitizados da imagem, arredondados100A; erro de leitura3%; interpolação log-log é aproximação, sem pico assimétrico",DocumentSha256=docHash};string file=Path.Combine(folder,"stamford-symmetric-50hz.csv");c.FaultTimeTrace=FaultTimeTrace.Import(p,c,metadata,file);var b=c.FaultTimeTrace;var r=FaultTimeTrace.Evaluate(p,c,b);Check(r.Accepted,r.Detail);Check(!r.ObservedInstantaneousPeakA.HasValue&&!r.DeclaredFaultPowerFactor.HasValue,"RMS does not invent peak or powerfactor");Near(r.MinimumSymmetricRmsA.Value,8000,"decrement minimum from data");Near(FaultTimeTrace.At(p,c,b,10),12300,"last point no extrapolation");Near(FaultTimeTrace.At(p,c,b,Math.Sqrt(2*5)),12300,"log-log constant segment");Near(FaultTimeTrace.At(p,c,b,Math.Sqrt(.001*.003)),Math.Sqrt(33900*3