;instant.Interpolation=TraceInterpolation.Linear;string instfile=Path.Combine(folder,"instant.csv");File.WriteAllText(instfile,"TimeSeconds;CurrentA\n0;0\n0.001;-100\n0.002;200\n0.003;-50\n");instant=FaultTimeTrace.Import(p,c,instant,instfile);var ir=FaultTimeTrace.Evaluate(p,c,instant);Near(ir.ObservedInstantaneousPeakA.Value,200,"instant observed absolute peak");Check(!ir.MinimumSymmetricRmsA.HasValue&&!ir.MaximumSymmetricRmsA.HasValue,"instant no invented RMS envelope");Near(FaultTimeTrace.At(p,c,instant,.0015),50,"signed linear interpolation");instant.Interpolation=TraceInterpolation.LogLog;Reject(instant.Validate,"instant logarithm disallowed");instant.Interpolation=TraceInterpolation.Linear;string output=Path.Combine(folder,"exported.csv");FaultTimeTrace.ExportSamples(instant,output);FaultTimeTrace.ExportSamples(instant,output);Check(File.Exists(output+".bak"),"sample export backup");using(var w=new StreamWriter(Path.Combine(folder,"consultas-stamford.csv"))){w.WriteLine("TimeSeconds;CurrentA");for(int i=0;i<b.Samples.Count;i++){double t=b.Samples[i].TimeSeconds;w.WriteLine(t.ToString("R",CultureInfo.InvariantCulture)+";"+FaultTimeTrace.At(p,c,b,t).ToString("R",CultureInfo.InvariantCulture));if(i+1<b.Samples.Count){t=Math.Sqrt(t*b.Samples[i+1].TimeSeconds);w.WriteLine(t.ToString("R",CultureInfo.InvariantCulture)+";"+FaultTimeTrace.At(p,c,b,t).ToString("R",CultureInfo.InvariantCulture));}}}var previous=Environment.GetEnvironmentVariable("CIRCUITO_QA_PREVIOUS_EXE");if(!String.IsNullOrEmpty(previous)){var asm=Assembly.LoadFile(Path.GetFullPath(previous));bool bad=false;try{asm.GetType("CircuitoStudio.Project").GetMethod("Load").Invoke(null,new object[]{projectFile});}catch(TargetInvocationException e){bad=e.InnerException is InvalidDataException;}Check(bad,"actual previous36 reader refuses trace capability");}var copied=ProjectEditing.DuplicateCircuit(p,p.Boards[0],c);Check(copied.FaultTimeTrace!=c.FaultTimeTrace&&copied.FaultTimeTrace.Samples[0]!=c.FaultTimeTrace.Samples[0],"duplicated circuit trace independent");Check(!FaultTimeTrace.Evaluate(p,copied,copied.FaultTimeTrace).Accepted,"duplicate circuit requires new physical case binding");p.Boards[0].Circuits.Remove(copied);var oldCulture=CultureInfo.CurrentCulture;try{System.Threading.Thread.CurrentThread.CurrentCulture=CultureInfo.GetCultureInfo("en-US");Check(FaultTimeTrace.Evaluate(p,c,b).Accepted,"context independent of decimal culture");}finally{System.Threading.Thread.CurrentThread.CurrentCulture=oldCulture;}var malformed=Path.Combine(folder,"bad.csv");File.WriteAllText(malformed,"TimeSeconds;CurrentA\n1;20\n0;10\n");Reject(()=>FaultTimeTrace.Import(p,c,metadata,malformed),"unordered import rejected");File.WriteAllText(malformed,"TimeSeconds;CurrentA\n0;NaN\n1;10\n");Reject(()=>FaultTimeTrace.Import(p,c,metadata,malformed),"nonfinite import rejected");Check(c.FaultTimeTrace==b&&b.Samples.Count==12,"bad imports leave attachment intact");Check(!FaultTimeTrace.Evaluate(p,c,null).Accepted,"missing trace no invented history");var sourcePower=p.Source.GeneratorRatedKva;p.Source.GeneratorRatedKva=100;Check(!FaultTimeTrace.Evaluate(p,c,b).Accepted,"generator rating change invalidates trace");p.Source.GeneratorRatedKva=sourcePower;var exact=EngineeringReport.Memory(p,Engineering.Analyze(p));Check(exact.Contains("não fornecido por envelope RMS")&&exact.Contains("desconhecido"),"memory explicitly separates peak RMS and FPcc");using(var form=new FaultTimeTraceForm(p,c)){var original=c.FaultTimeTrace;Check(!form.Changed&&form.EvaluateDraft(false).Accepted&&Object.ReferenceEquals(original,c.FaultTimeTrace),"form evaluate without mutation");form.ImportDraft(file);Check(Object.ReferenceEquals(original,c.FaultTimeTrace),"import draft no live mutation");Near(form.Query(.4),8000,"form query accepted domain");Reject(()=>form.Query(0),"form query cannot extrapolate");Reject(()=>form.ImportDraft(malformed),"form import malformed atomic");Check(Object.ReferenceEquals(original,c.FaultTimeTrace)&&!form.Changed,"failed draft import preserves attachment");form.EvaluateDraft(true);Check(form.Changed&&c.FaultTimeTrace!=original&&c.FaultTimeTrace.Samples[0]!=original.Samples[0],"form save deep clone");if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(5,5);form.Show();Application.DoEvents();form.Refresh();form.Update();using(var bmp=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var g=Graphics.FromImage(bmp))g.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bmp.Save(Path.Combine(folder,"historico-gerador.png"));}form.Hide();}}var rl=Project.CreateSample();rl.Source.ShortCircuitKA=10;using(var form=new FaultWaveformForm(rl,rl.Boards[0],rl.Boards[0].Circuits[0])){if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(15,15);form.Show();Application.DoEvents();form.Refresh();form.Update();using(var bmp=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var g=Graphics.FromImage(bmp))g.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bmp.Save(Path.Combine(folder,"onda-rl.png"));}form.Hide();}}p.Source.Model=SourceModel.UPS;p.Source.UPSMode=UPSOperatingMode.Inversor;p.Source.UPSCurrentLimitKA=2;var upsMetadata=metadata.Copy();upsMetadata.Kind=FaultTraceKind.InstantaneousSigned;upsMetadata.Interpolation=TraceInterpolation.Linear;upsMetadata.EquipmentReference="UPS sintéticaQA em inversor";upsMetadata.Reference="Amostras de corrente sintéticas, teste de caminho distinto";upsMetadata.Conditions="Inversor; dados de teste, sem inferência de tensão/RL";var upsTrace=FaultTimeTrace.Import(p,c,upsMetadata,instfile);Check(FaultTimeTrace.Evaluate(p,c,upsTrace).Accepted,"UPS external time samples without impedance conversion");Check(Engineering.Analyze(p).For(c).FaultOriginDynamics==null,"UPS inverse waveform remains non-RL");Console.WriteLine("PASS: "+n+" fault-time trace assertions");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
